changeList.full_content:
import {getCountryCode, getLanguage} from '@smart/locale-service';
import {parseAdbContextCookie, parseLoginUserDetailsCookie} from '@smart/utils';
import type {
  APIGatewayProxyEvent,
  APIGatewayProxyHandler,
  APIGatewayProxyResult,
} from 'aws-lambda';
import {z} from 'zod';
import {commonQueryParamsSchema} from '../common-query-params-schema';
import {normalizeEventHeaders} from '../normalize-event-headers';
import {
  ecomPathname,
  getApiEndpoint,
  getApiHeaders,
} from '../utils/api-endpoint';
import {createProductPricesModel} from './create-product-prices-model';
import type {CreateProductPricesResponse} from './create-product-prices-model';

const queryParamsSchema = commonQueryParamsSchema.extend({
  productCode: z.string(),
});

export const handler: APIGatewayProxyHandler = async (
  data: APIGatewayProxyEvent,
  {awsRequestId},
): Promise<APIGatewayProxyResult> => {
  const queryParams = queryParamsSchema.safeParse(
    data.queryStringParameters ?? {},
  );
  if (!queryParams.success) {
    return {statusCode: 400, body: JSON.stringify(queryParams.error)};
  }

  const {envName, marketId, languageTag, productCode} = queryParams.data;
  normalizeEventHeaders(data);

  if (envName !== `prod`) {
    console.debug(
      `PRODUCT DETAILS EVENT FOR TOTAL AND DEFAULT LEASING PRICE:\n${JSON.stringify(
        data,
      )}`,
    );
  }

  try {
    const apiEndpoint = getApiEndpoint(envName);
    const apiHeaders = getApiHeaders();

    const urlParams = new URLSearchParams({
      fields: `FULL`,
      productCode,
      lang: getLanguage(languageTag),
    });

    // Parse cookies to extract user-id and customer-id
    const cookie = data.headers?.[`cookie`] || data.headers?.[`Cookie`] || ``;
    const loginUserDetails = cookie
      ? parseLoginUserDetailsCookie(cookie)
      : undefined;
    const adbContext = parseAdbContextCookie(cookie);

    const userId = loginUserDetails?.userId;
    const customerId = adbContext?.customerUserId;

    const signal = {
      method: `GET`,
      headers: {
        ...apiHeaders,
        'base-site-id': `smart-${getCountryCode(marketId).toLowerCase()}`,
        ...(userId && {'user-id': userId}),
        ...(customerId && {'customer-id': customerId}),
      },
    };

    const url = `${apiEndpoint}${ecomPathname}/products/product?${urlParams.toString()}`;
    const response = await fetch(url, signal);
    const ProductDetailsResult = (await response.json()) as {
      'response-data': CreateProductPricesResponse;
    };

    const productDetailModel = createProductPricesModel(
      ProductDetailsResult[`response-data`],
    );

    return {
      statusCode: 200,
      headers: {
        'Content-Type': `application/json`,
        'Cache-Control': `no-store`,
        'X-Lambda-Request-Id': awsRequestId,
      },
      body: JSON.stringify(productDetailModel),
    };
  } catch (error) {
    console.info(`product details model`, error);
  }

  return {
    statusCode: 500,
    body: ``,
    headers: {'X-Lambda-Request-Id': awsRequestId},
  };
};

export const templateStrings = {
  PN18: `{{PN18}}`,
} as const;

export enum UsedFeatureFlags {
  ENABLE_ENERGYLABEL_MODAL = `enable-energylabel-modal`,
  ENABLE_CUSTOMIZER_V2 = `enable-customizer-v2`,
  HIDE_SALES_TOOLS_LEASING_RATE = `hide-sales-tools-leasing-rate`,
  ENABLE_DISCOUNT_IN_SALES_TOOL = `enable-discount-in-sales-tool`,
  INCLUDE_VAT_FOR_SME_CASH_BUY = `include-vat-for-sme-cash-buy`,
}

