@use '@smart/web-components/dist/scss/variables' as *;

.discountPricing {
  &__label-wrapper {
    max-width: 50%;
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    align-items: baseline;
  }

  &__label {
    color: var(--c-mid-contrast);
    margin-right: var(--spacing-50);
  }

  &__price-wrapper {
    display: flex;
    flex-direction: row;
    align-items: flex-end;
    gap: var(--spacing-50);
  }

  &__price-discounted {
    color: var(--sig-error); // Red color for discounted price
  }

  &__base-price-wrapper {
    display: flex;
    flex-direction: row;
    align-items: flex-start;
    gap: var(--spacing-50);
    flex-wrap: wrap;

    @include breakpoint(l) {
      max-width: var(--col-3);
    }
  }

  &__base-price-content {
    flex: 1;
    min-width: 0;
    letter-spacing: -0.04em;
  }

  &__base-price {
    display: inline;
    text-decoration: line-through;
    text-decoration-color: var(--sig-error); // Red strikethrough
    font-size: calc(var(--font-size-lgl-100) + 1px);
  }

