+import {Text} from '@smart/react-components';
+import {useTranslations} from '@smart/react-utils';
+import * as React from 'react';
+import type {PromotionPriceEntry} from '../../../bff/product-prices/create-product-prices-model';
+import {useAppModel} from '../../contexts';
+import styles from './discount-pricing.module.scss';
+
+const baseClass = `discountPricing`;
+
+export type DiscountPricingProps = {
+  buyPrice?: string; // Discounted final price (e.g., "€45,000.00")
+  cashBuyTaxLabel: string | undefined; // VAT label (e.g., "incl. VAT")
+  basePrice?: string; // Original price before discount (e.g., "€50,000.00")
+  discount?: PromotionPriceEntry; // Discount data object
+  cashBuyPriceLabel?: string; // Cash buy price label (e.g., "Kaufpreis")
+  cashBuyPriceReference?: string; // Cash buy price reference superscript
+};
+
+export const DiscountPricing = ({
+  buyPrice,
+  cashBuyTaxLabel,
+  basePrice,
+  discount,
+  cashBuyPriceLabel,
+  cashBuyPriceReference,
+}: DiscountPricingProps): JSX.Element => {
+  const {
+    appModel: {translations},
+  } = useAppModel();
+  const {t} = useTranslations(translations ?? {});
+  const parts = t(`discount.listPriceDiscription`).split(`{{price}}`);
+  const MAX_BADGE_LENGTH = 25;
+
+  // Determine discount tag value based on usePercentageDiscount flag
+  const usePercentageDiscount = t(`discount.usePercentageDiscount`) === `true`;
+  const discountTagValue = usePercentageDiscount
+    ? discount?.totalDiscountPercentage !== undefined
+      ? `${discount.totalDiscountPercentage}%`
+      : ``
+    : (discount?.formattedValue ?? ``);
+
+  // Generate badge text and truncate if necessary
+  const getBadgeText = (): string => {
+    const badgeText = t(`discount.tag`).replace(
+      `{{discountTagPrice}}`,
+      discountTagValue,
+    );
+    return badgeText.length > MAX_BADGE_LENGTH
+      ? `${badgeText.slice(0, MAX_BADGE_LENGTH - 1)}…`
+      : badgeText;
+  };
+
+  return (
+    <div className={styles[`${baseClass}__label-wrapper`]}>
+      {/* Price Label */}
+      <Text className={styles[`${baseClass}__label`]} variant={`p-100`}>
+        {cashBuyPriceLabel ?? t(`discount.priceLabel`)}
+        {(cashBuyPriceReference || t(`discount.priceLabelSuperscript`)) && (
+          <sup>
+            {cashBuyPriceReference ?? t(`discount.priceLabelSuperscript`)}
+          </sup>
+        )}
+      </Text>
+
+      {/* Discounted Price */}
+      <div className={styles[`${baseClass}__price-wrapper`]}>
+        <Text
+          className={styles[`${baseClass}__price-discounted`]}
+          variant={`hl-50`}
+        >
+          {buyPrice}
+        </Text>
+        {cashBuyTaxLabel && (
+          <Text
+            className={styles[`${baseClass}__description`]}
+            variant={`lgl-100`}
+          >
+            {cashBuyTaxLabel}
+          </Text>
+        )}
+      </div>
+
+      {/* Original Price with Strikethrough + Discount Badge */}
+      <div className={styles[`${baseClass}__base-price-wrapper`]}>
+        <div className={styles[`${baseClass}__base-price-content`]}>
+          {parts[0] && (
+            <Text
+              className={styles[`${baseClass}__base-price-label`]}
+              variant={`lgl-100`}
+            >
+              {parts[0]}
+              {` `}
+            </Text>
+          )}
+          {basePrice && (
+            <>
+              <Text
+                className={styles[`${baseClass}__base-price`]}
+                variant={`lgl-100`}
+              >
+                {basePrice}
+              </Text>
+            </>
+          )}
+          {parts[1] ? (
+            <Text
+              className={styles[`${baseClass}__base-price-label`]}
+              variant={`lgl-100`}
+            >
+              {` `}
+              {parts[1]}
+              {` `}
+            </Text>
+          ) : (
+            <>{` `}</>
+          )}
+          {t(`discount.tag`) && (
+            <div className={styles[`${baseClass}__discount-badge`]}>
+              {getBadgeText()}
+              {t(`discount.tagSuperscript`) && (
+                <sup>{t(`discount.tagSuperscript`)}</sup>
+              )}
+            </div>
+          )}
+        </div>
+      </div>
+    </div>
+  );
+};

