changeList.full_content:
@use '@smart/web-components/dist/scss/variables' as *;

.img {
  object-fit: contain;
  width: 100%;
  height: 100px;
}

.container {
  position: relative;
  cursor: pointer;
  &:hover {
    .card {
      background-color: var(--bg-level-2);
    }
  }
  &:active {
    .card {
      background-color: var(--bg-level-3);
    }
  }
}

.card {
  transition: background-color var(--duration-f3) var(--motion-ease-emotional);
}

.selection {
  position: absolute;
  top: var(--spacing-300);
  right: var(--spacing-300);
}

.priceGap {
  gap: var(--spacing-100);

  @include breakpoint(l) {
    gap: var(--spacing-300);
  }
}

