changeList.full_content:
import {SegmentedControl, Theme} from '@smart/react-components';
import React from 'react';
import {OView, type View} from '../../../types/feature-app';
import {useProducts} from '../../contexts';
import {PageName, useTracking} from '../../hooks/use-tracking';
import {useTranslations} from '../../hooks/use-translations';
import {findMostMatchingProduct} from '../../utils/product';
import styles from './model-select.module.scss';
export const ModelSelect = ({view}: {view: View}) => {
  const {line, model, models, setProduct, product} = useProducts();
  const track = useTracking();
  const {t} = useTranslations({model});

  const modelsListItems = models.map(({code, name}) => ({
    value: code,
    label: name,
  }));

  const onModelChange = (newCode: string) => {
    const currModel = models.find((mod) => newCode === mod.code);

    const newLine =
      currModel?.lines.find(
        (l) => l.name.toLowerCase() === line?.name?.toLowerCase(),
      ) ?? currModel?.lines[0];

    if (!newLine) return;
    const newProduct = findMostMatchingProduct(product, newLine.products);
    if (!newProduct) return;
    setProduct(newProduct.code);
    track.page(PageName.LINES, newProduct.code);
  };

  return (
    <Theme theme={view === OView.VNT ? `dark` : `light`}>
      <div className={styles.modelSelect}>
        <SegmentedControl
          value={model.code}
          label={t(`modelsTitle`)}
          onValueChange={onModelChange}
          children={modelsListItems.map((m) => (
            <SegmentedControl.Item key={m.value} value={m.value}>
              {m.label}
            </SegmentedControl.Item>
          ))}
        />
      </div>
    </Theme>
  );
};

