@use '@smart/web-components/dist/scss/variables' as *;
@use 'sass:map';
.product-card {
  width: 100%;
  display: flex;
  min-height: 70vh;
  @include breakpoint(m) {
    min-height: 500px;
  }
  &__image-container {
    width: 100%;
    height: 140px;
    @include breakpoint(m) {
      width: calc(var(--col-16) / 3);
      height: 500px;
      padding-bottom: 50px;
    }
    display: flex;
    align-items: center;
    background-color: var(--bg-level-2);
    justify-content: center;
    .img {
      width: 100%;
      width: 100%;
      @include breakpoint(m) {
        height: 260px;
      }
      object-fit: contain;
    }
  }

  &__content {
    flex: 1;
    padding: var(--spacing-500) var(--spacing-200);
    @include breakpoint(m) {
      padding: var(--spacing-400) var(--spacing-300) var(--spacing-400)
        var(--spacing-500);
    }
  }

  &__title {
    margin: var(--spacing-100) 0;
  }

  &__description {
    max-width: 305px;
    word-wrap: break-word;
    margin-bottom: var(--spacing-200);

    @include breakpoint(m) {
      margin-bottom: var(--spacing-400);
    }
  }

  &__hightlights-title {
    margin-bottom: var(--spacing-100);
  }

  &__hightlights-list {
    padding-left: var(--spacing-300);
  }

  &__price-description {
    margin-right: 10px;
    @include breakpoint(m) {
      margin-right: 12px;
    }
  }

  &__price-divider {
    margin: 0;
    height: unset;
    @include breakpoint(l) {
      margin: 0 var(--spacing-300);
    }
  }
  &__energyLabel {
    margin-right: var(--spacing-200);
  }

  &__buttons-wrapper {
    gap: var(--spacing-300);
    @include breakpoint(m) {
      gap: var(--spacing-400);
    }
  }
}

.priceGap {
  gap: var(--spacing-100);
  @include breakpoint(l) {
    gap: var(--spacing-400);
  }
}

