import type {EndpointDirectoryV3} from '@smart/endpoint-directory';
import type {PriceTypeV1} from '@smart/price-preferences-provider';
import {Text} from '@smart/react-components';
import type {MarketId} from '@smart/types';
import {PAYMENT_TYPE} from '@smart/types';
import type {LabelsForMarketCustomerTypePaymentType} from '@smart/utils';
import {getLabelsForMarketPriceTypePaymentType} from '@smart/utils';
import React from 'react';
import {useAppModel} from '../../contexts';
import {useLocale} from '../../hooks/use-locale';
import type {PriceKey} from '.';
interface TaxLabelProps {
  deprecatedVatLabel: string | undefined;
  priceKey: PriceKey;
  priceType: PriceTypeV1;
  endpointDirectory: EndpointDirectoryV3;
  variant?: string;
  style?: React.CSSProperties;
  color?: string;
}
export const TaxLabel = ({
  deprecatedVatLabel,
  priceKey,
  priceType,
  endpointDirectory,
  variant = `p-100`,
  style = {fontSize: `14px`},
  color = `c-mid-contrast`,
}: TaxLabelProps) => {
  const {
    appModel: {customiserContent},
  } = useAppModel();
  const {marketId, language} = useLocale();

  let newTaxLabel;
  if (customiserContent?.excludesTax && customiserContent?.includesTax) {
    const {vatLabel} = getLabelsForMarketPriceTypePaymentType({
      marketId: marketId as MarketId,
      labels: {
        excludeVatLabel: customiserContent?.excludesTax,
        includesVatLabel: customiserContent?.includesTax,
      },
      priceType,
      paymentType:
        priceKey === `totalPrice` ? PAYMENT_TYPE.CASH : PAYMENT_TYPE.LEASING,
      config:
        customiserContent?.commonConfig as LabelsForMarketCustomerTypePaymentType,
    });

    if (vatLabel && typeof vatLabel === `string`) {
      newTaxLabel = vatLabel;
    }
  }

  if (endpointDirectory.envName !== `prod`) {
    console.debug({
      'AEM Tax Label Path': newTaxLabel
        ? `/content/common/${marketId}/${language}/common-attributes`
        : `/content/stock-search/${marketId}/${language}/stock-search-content`,
    });
  }

  return (
    <Text style={style} as={`span`} color={color} variant={variant}>
      {newTaxLabel ?? deprecatedVatLabel}
    </Text>
  );
};

