import type {EndpointDirectoryV3} from '@smart/endpoint-directory';
import type {LocaleV3} from '@smart/locale-service';
import type {StandardEquipmentsModel} from '../../types/vehicle-line-data';

interface FetchStandardEquipmentsModelOptions {
  readonly featureCode: string;
  readonly locale: LocaleV3;
  readonly endpointDirectory: EndpointDirectoryV3;
}

export async function fetchStandardEquipmentsModel(
  baseUrl: string = ``,
  options: FetchStandardEquipmentsModelOptions,
  signal: AbortSignal,
): Promise<StandardEquipmentsModel[]> {
  const {locale, endpointDirectory, featureCode} = options;
  const {envName, preview} = endpointDirectory;
  const {marketId, languageTag} = locale;

  const searchParams = new URLSearchParams({
    envName,
    preview: String(preview),
    marketId,
    languageTag,
    featureCode,
  });

  try {
    const url = `${baseUrl}/bff/standard-equipments-model?${searchParams.toString()}`;

    const response = await fetch(url, {signal});

    if (!response.ok) {
      console.error(
        `Could not fetch Feature code details or feature code does not exist!`,
      );
      return [];
    }

    const data = (await response.json()) as StandardEquipmentsModel[];
    return Array.isArray(data) ? data : [];
  } catch (error) {
    if (signal.aborted) {
      throw new Error(`Request aborted.`);
    }
    console.error(
      `Could not fetch Feature code details or feature code does not exist!`,
    );
    return [];
  }
}

