  LeasingPrice,
  PcpLeasingPrice,
  PromoBadgePrice,
  TotalPrice,
} from '../bff/product-prices/create-product-prices-model';

export const OView = {
  // Interior view
  VNT: `VNT`,
  // Line view
  VLN: `VLN`,
  // Exterior view
  VEX: `VEX`,
  // Battery view
  VBT: `VBT`,
  // Line Overview
  VLO: `VLO`,
};

export type View = (typeof OView)[keyof typeof OView];

export interface Classification {
  /**
   * Code of the classification
   * @type {string}
   * @memberof Classification
   */
  code?: string;
  /**
   * List of features for given classification
   * @type {Array<Feature>}
   * @memberof Classification
   */
  features?: Array<Feature>;
  /**
   * Name of the classification
   * @type {string}
   * @memberof Classification
   */
  name?: string;
}

export interface Feature {
  /**
   * Code of the feature
   * @type {string}
   * @memberof Feature
   */
  code?: string;
  /**
   * Flag defining it feature is comparable
   * @type {boolean}
   * @memberof Feature
   */
  comparable?: boolean;
  /**
   * Description of the feature
   * @type {string}
   * @memberof Feature
   */
  description?: string;
  /**
   *
   * @type {FeatureUnit}
   * @memberof Feature
   */
  featureUnit?: FeatureUnit;
  /**
   * List of feature values
   * @type {Array<FeatureValue>}
   * @memberof Feature
   */
  featureValues?: Array<FeatureValue>;
  /**
   * Name of the feature
   * @type {string}
   * @memberof Feature
   */
  name?: string;
  /**
   * Range number of the reature
   * @type {boolean}
   * @memberof Feature
   */
  range?: boolean;
  /**
   * Type of the feature
   * @type {string}
   * @memberof Feature
   */
  type?: string;
}

export interface FeatureUnit {
  /**
   * Name of the feature unit
   * @type {string}
   * @memberof FeatureUnit
   */
  name?: string;
  /**
   * Symbol of the feature unit
   * @type {string}
   * @memberof FeatureUnit
   */
  symbol?: string;
  /**
   * Type of the feature unit
   * @type {string}
   * @memberof FeatureUnit
   */
  unitType?: string;
}

export interface FeatureValue {
  /**
   * Value of the feature
   * @type {string}
   * @memberof FeatureValue
   */
  value?: string;
}

export interface ProductPricesModel {
  pn18: string;
  purchasable: string;
  price: TotalPrice;
  netPrice: TotalPrice;
  leasingPrice: LeasingPrice;
  pcpLeasingPrice: PcpLeasingPrice;
  netLeasingPrice: LeasingPrice;
  modelYear?: string;
  lineName?: string;
  classifications: Classification[];
  stockLevelStatus: string | undefined;
  lineCode?: string;
  earliestBeautifiedLeadTime: string | undefined;
  name: string;
  promoBadgePrice?: PromoBadgePrice;
}

export type Disclaimer = {reference: string; legalText: {plaintext: string}};

